const normalizePreviewQueryValue = (key: string, value: unknown) => {
  const stringValue = String(value)

  if (key !== 'serverRelativeUrl') {
    return stringValue
  }

  try {
    return decodeURIComponent(stringValue)
  } catch {
    return stringValue
  }
}

export default defineEventHandler(async (event) => {
  const config = useRuntimeConfig()

  if (config.mockEnabled) {
    return {
    "data": "",
    "fileName": "Non‑Disclosure Agreement Playbook.docx",
    "contentType": "application/octet-stream; charset=utf-8"
}
  }

  try {
    const query = getQuery(event)
    const searchParams = new URLSearchParams()

    Object.entries(query).forEach(([key, value]) => {
      if (Array.isArray(value)) {
        value.forEach(item => searchParams.append(key, normalizePreviewQueryValue(key, item)))
        return
      }

      if (value !== undefined && value !== null) {
        searchParams.append(key, normalizePreviewQueryValue(key, value))
      }
    })

    const notificationApiPrefix = '/api/r/internal'
    const queryString = searchParams.toString()
    const previewPath = `${notificationApiPrefix}/ecology_oa/company_document/preview${queryString ? `?${queryString}` : ''}`
    const response = await $fetch.raw<Record<string, unknown>>(`${config.public.apiBase}${previewPath}`, {
      method: 'GET',
      headers: getForwardHeaders(event),
    })

    forwardSetCookieHeaders(event, response)

    return response._data
  } catch (error: unknown) {
    const errorRecord = error && typeof error === 'object' ? error as Record<string, unknown> : {}
    const statusCode = Number(errorRecord.statusCode || errorRecord.status) || 500
    const statusMessage = typeof errorRecord.statusMessage === 'string'
      ? errorRecord.statusMessage
      : typeof errorRecord.message === 'string'
        ? errorRecord.message
        : 'Company document preview API failed'

    console.error('Company document preview API error:', {
      statusCode,
      statusMessage,
      data: errorRecord.data,
    })

    throw createError({
      statusCode,
      statusMessage,
      data: errorRecord.data,
    })
  }
})
